import 'dart:convert';
import 'package:http/http.dart' as http;

class Todo {
  const Todo({required this.id, required this.title, required this.done});
  final int id;
  final String title;
  final bool done;

  factory Todo.fromJson(Map<String, dynamic> json) => switch (json) {
        {'id': int id, 'title': String title, 'completed': bool done} =>
          Todo(id: id, title: title, done: done),
        _ => throw FormatException('Bad todo JSON: $json'),
      };
}

Future<List<Todo>> fetchTodos(http.Client client) async {
  final uri = Uri.parse('https://jsonplaceholder.typicode.com/todos?_limit=5');
  final res = await client.get(uri).timeout(const Duration(seconds: 10));
  if (res.statusCode != 200) throw Exception('HTTP ${res.statusCode}');
  final list = jsonDecode(res.body) as List<dynamic>;
  return [for (final item in list) Todo.fromJson(item as Map<String, dynamic>)];
}

