class _LikeButtonState extends State<LikeButton> {
  int likes = 0;
  @override
  Widget build(BuildContext context) => TextButton(
      key: const ValueKey('like'), onPressed: () => setState(() => likes++), child: Text('$likes likes'));
}
void main() {
  testWidgets('tapping like increments the count', (tester) async {
    await tester.pumpWidget(const MaterialApp(home: Scaffold(body: LikeButton())));
    expect(find.text('0 likes'), findsOneWidget);
    await tester.tap(find.byKey(const ValueKey('like')));
    await tester.pump();                       // rebuild after setState

    expect(find.text('1 likes'), findsOneWidget);
    expect(find.text('0 likes'), findsNothing);
  });
}

import 'package:flutter/foundation.dart';
class Product { const Product(this.id, this.name); final int id; final String name; }
abstract interface class ProductApi { Future<List<Map<String, dynamic>>> fetchAll(); }
class ProductRepository {                              // data layer
  ProductRepository(this._api);
  final ProductApi _api;
  List<Product>? _cache;
  Future<List<Product>> products() async => _cache ??= [
        for (final json in await _api.fetchAll()) Product(json['id'] as int, json['name'] as String)
      ];
}
class ProductListViewModel extends ChangeNotifier {   // UI layer
  ProductListViewModel(this._repo);
  final ProductRepository _repo;
  List<Product> items = [];
  bool loading = false;
  Object? error;

  Future<void> load() async {
    loading = true; error = null; notifyListeners();
    try { items = await _repo.products(); } catch (e) { error = e; }
    loading = false; notifyListeners();
  }
}
