import 'package:flutter/widgets.dart';
// A widget that creates its own RenderObject: the bottom layer of the three trees.
class ColoredSquare extends LeafRenderObjectWidget {
  const ColoredSquare({super.key, required this.color});
  final Color color;
  @override
  RenderObject createRenderObject(BuildContext context) => _RenderSquare(color);
  @override
  void updateRenderObject(BuildContext context, _RenderSquare renderObject) {
    renderObject.color = color;          // element reuses the render object
  }
}
class _RenderSquare extends RenderBox {
  _RenderSquare(this._color);
  Color _color;
  set color(Color c) { if (c != _color) { _color = c; markNeedsPaint(); } }  // paint only

  @override
  void performLayout() => size = constraints.constrain(const Size.square(48));  // layout

  @override
  void paint(PaintingContext context, Offset offset) =>
      context.canvas.drawRect(offset & size, Paint()..color = _color);
}

