import 'dart:math' as math;
import 'package:flutter/material.dart';
class RingPainter extends CustomPainter {
  RingPainter({required this.progress, required this.color}) : super(repaint: progress);
  final Animation<double> progress;     // repaints on every tick, no widget rebuild
  final Color color;
  @override
  void paint(Canvas canvas, Size size) {
    final center = size.center(Offset.zero);
    final radius = size.shortestSide / 2 - 6;
    Paint stroke(Color c) => Paint()
      ..style = PaintingStyle.stroke..strokeWidth = 12..strokeCap = StrokeCap.round..color = c;
    final track = stroke(color.withValues(alpha: 0.2)), arc = stroke(color);
    canvas.drawCircle(center, radius, track);
    canvas.drawArc(Rect.fromCircle(center: center, radius: radius),
        -math.pi / 2, 2 * math.pi * progress.value, false, arc);
  }

  @override
  bool shouldRepaint(RingPainter old) => old.color != color || old.progress != progress;
}

// Usage inside a State with an AnimationController `_c`:
// RepaintBoundary(child: CustomPaint(size: const Size.square(120),
//     painter: RingPainter(progress: _c, color: Colors.teal)))
